PRODUCTION_SOURCE = '"""\nOLA-040\nOracle Canonical Persisted Cohort Capture Port\n\nIn-process exact-object handoff boundary for one successfully persisted\ncanonical acquisition cohort.\n\nPurpose:\n- capture the exact CanonicalObservation objects produced by the OLA-017 cycle\n  before scheduler result projection removes non-canonical objects\n- key captures by acquisition_batch_id\n- preserve exact observation ordering and object identity\n- enforce one write per acquisition batch\n- enforce one consume per acquisition batch\n- expose immutable metadata for audit without serializing observation objects\n  into scheduler kwargs or scheduler results\n\nThis is a capture port only. It does not perform persistence, lineage,\nintelligence interpretation, scoring, alerting, Q Series handoff,\nauthorization, or execution.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom hashlib import sha256\nimport json\nfrom threading import RLock\nfrom types import MappingProxyType\nfrom typing import Any, Mapping, Sequence\n\nfrom .oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n)\n\n\nSCHEMA_VERSION = "OLA-040"\nENGINE_ID = "OLA-040"\nCAPTURE_TYPE = "oracle_canonical_persisted_cohort_capture"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass CanonicalPersistedCohortCaptureContractError(ValueError):\n    """Raised when OLA-040 capture input is malformed."""\n\n\nclass CanonicalPersistedCohortCaptureInvariantError(RuntimeError):\n    """Raised when permanent OLA-040 invariants are violated."""\n\n\ndef _require_non_empty_string(\n    value: Any,\n    field_name: str,\n) -> str:\n    if not isinstance(value, str):\n        raise CanonicalPersistedCohortCaptureContractError(\n            f"{field_name} must be a string"\n        )\n\n    normalized = value.strip()\n\n    if not normalized:\n        raise CanonicalPersistedCohortCaptureContractError(\n            f"{field_name} must not be empty"\n        )\n\n    return normalized\n\n\ndef _stable_hash(value: Any) -> str:\n    encoded = json.dumps(\n        value,\n        sort_keys=True,\n        separators=(",", ":"),\n        ensure_ascii=False,\n        allow_nan=False,\n    ).encode("utf-8")\n\n    return sha256(encoded).hexdigest()\n\n\n@dataclass(frozen=True, slots=True)\nclass CanonicalPersistedCohortCapture:\n    schema_version: str\n    engine_id: str\n    capture_type: str\n    acquisition_batch_id: str\n    canonical_count: int\n    canonical_observations: tuple[CanonicalObservation, ...]\n    observation_ids: tuple[str, ...]\n    source_market_ids: tuple[str, ...]\n    content_hashes: tuple[str, ...]\n    replay_hashes: tuple[str, ...]\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n    capture_hash: str\n\n    @classmethod\n    def create(\n        cls,\n        *,\n        canonical_observations: Sequence[CanonicalObservation],\n    ) -> "CanonicalPersistedCohortCapture":\n        observations = tuple(canonical_observations)\n\n        if not observations:\n            raise CanonicalPersistedCohortCaptureContractError(\n                "canonical_observations must not be empty"\n            )\n\n        batch_ids: set[str] = set()\n        observation_ids: list[str] = []\n        observation_id_set: set[str] = set()\n        source_market_ids: list[str] = []\n        source_market_id_set: set[str] = set()\n        content_hashes: list[str] = []\n        replay_hashes: list[str] = []\n\n        for observation in observations:\n            if not isinstance(\n                observation,\n                CanonicalObservation,\n            ):\n                raise CanonicalPersistedCohortCaptureContractError(\n                    "capture requires CanonicalObservation records"\n                )\n\n            if observation.observation_type != "market_snapshot":\n                raise CanonicalPersistedCohortCaptureContractError(\n                    "OLA-040 accepts only market_snapshot observations"\n                )\n\n            batch_id = _require_non_empty_string(\n                observation.acquisition_batch_id,\n                "observation.acquisition_batch_id",\n            )\n            observation_id = _require_non_empty_string(\n                observation.observation_id,\n                "observation.observation_id",\n            )\n\n            payload = dict(observation.payload)\n            source_market_id = _require_non_empty_string(\n                payload.get("source_market_id"),\n                "observation.payload.source_market_id",\n            )\n\n            if observation_id in observation_id_set:\n                raise CanonicalPersistedCohortCaptureContractError(\n                    "duplicate observation_id within capture"\n                )\n\n            if source_market_id in source_market_id_set:\n                raise CanonicalPersistedCohortCaptureContractError(\n                    "duplicate source_market_id within capture"\n                )\n\n            batch_ids.add(batch_id)\n            observation_id_set.add(observation_id)\n            source_market_id_set.add(source_market_id)\n            observation_ids.append(observation_id)\n            source_market_ids.append(source_market_id)\n            content_hashes.append(\n                _require_non_empty_string(\n                    observation.content_hash,\n                    "observation.content_hash",\n                )\n            )\n            replay_hashes.append(\n                _require_non_empty_string(\n                    observation.replay_hash,\n                    "observation.replay_hash",\n                )\n            )\n\n        if len(batch_ids) != 1:\n            raise CanonicalPersistedCohortCaptureContractError(\n                "captured cohort must share one acquisition_batch_id"\n            )\n\n        acquisition_batch_id = next(iter(batch_ids))\n\n        metadata_payload = {\n            "schema_version": SCHEMA_VERSION,\n            "engine_id": ENGINE_ID,\n            "capture_type": CAPTURE_TYPE,\n            "acquisition_batch_id": acquisition_batch_id,\n            "canonical_count": len(observations),\n            "observation_ids": observation_ids,\n            "source_market_ids": source_market_ids,\n            "content_hashes": content_hashes,\n            "replay_hashes": replay_hashes,\n            "read_only": READ_ONLY,\n            "execution_allowed": EXECUTION_ALLOWED,\n            "execution_adapter_resolved": EXECUTION_ADAPTER_RESOLVED,\n            "execution_adapter_invoked": EXECUTION_ADAPTER_INVOKED,\n            "trade_authorization_allowed": TRADE_AUTHORIZATION_ALLOWED,\n            "order_placement_allowed": ORDER_PLACEMENT_ALLOWED,\n            "funds_moved": FUNDS_MOVED,\n            "portfolio_mutated": PORTFOLIO_MUTATED,\n        }\n\n        capture = cls(\n            schema_version=SCHEMA_VERSION,\n            engine_id=ENGINE_ID,\n            capture_type=CAPTURE_TYPE,\n            acquisition_batch_id=acquisition_batch_id,\n            canonical_count=len(observations),\n            canonical_observations=observations,\n            observation_ids=tuple(observation_ids),\n            source_market_ids=tuple(source_market_ids),\n            content_hashes=tuple(content_hashes),\n            replay_hashes=tuple(replay_hashes),\n            read_only=READ_ONLY,\n            execution_allowed=EXECUTION_ALLOWED,\n            execution_adapter_resolved=EXECUTION_ADAPTER_RESOLVED,\n            execution_adapter_invoked=EXECUTION_ADAPTER_INVOKED,\n            trade_authorization_allowed=TRADE_AUTHORIZATION_ALLOWED,\n            order_placement_allowed=ORDER_PLACEMENT_ALLOWED,\n            funds_moved=FUNDS_MOVED,\n            portfolio_mutated=PORTFOLIO_MUTATED,\n            capture_hash=_stable_hash(metadata_payload),\n        )\n\n        capture.assert_invariants()\n        return capture\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "schema version invariant violated"\n            )\n\n        if self.engine_id != ENGINE_ID:\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "engine identity invariant violated"\n            )\n\n        if self.capture_type != CAPTURE_TYPE:\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "capture type invariant violated"\n            )\n\n        if self.canonical_count <= 0:\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "canonical count must be positive"\n            )\n\n        if self.canonical_count != len(\n            self.canonical_observations\n        ):\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "canonical observation count invariant violated"\n            )\n\n        if len(self.observation_ids) != self.canonical_count:\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "observation identity count invariant violated"\n            )\n\n        if len(self.source_market_ids) != self.canonical_count:\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "market identity count invariant violated"\n            )\n\n        if len(self.content_hashes) != self.canonical_count:\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "content hash count invariant violated"\n            )\n\n        if len(self.replay_hashes) != self.canonical_count:\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "replay hash count invariant violated"\n            )\n\n        if len(set(self.observation_ids)) != self.canonical_count:\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "observation identity uniqueness invariant violated"\n            )\n\n        if len(set(self.source_market_ids)) != self.canonical_count:\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "market identity uniqueness invariant violated"\n            )\n\n        if self.observation_ids != tuple(\n            observation.observation_id\n            for observation in self.canonical_observations\n        ):\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "exact observation ordering invariant violated"\n            )\n\n        if self.content_hashes != tuple(\n            observation.content_hash\n            for observation in self.canonical_observations\n        ):\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "content hash binding invariant violated"\n            )\n\n        if self.replay_hashes != tuple(\n            observation.replay_hash\n            for observation in self.canonical_observations\n        ):\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "replay hash binding invariant violated"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise CanonicalPersistedCohortCaptureInvariantError(\n                "OLA-040 read-only authority invariants violated"\n            )\n\n    def to_canonical_metadata(\n        self,\n    ) -> Mapping[str, Any]:\n        return MappingProxyType(\n            {\n                "schema_version": self.schema_version,\n                "engine_id": self.engine_id,\n                "capture_type": self.capture_type,\n                "acquisition_batch_id": self.acquisition_batch_id,\n                "canonical_count": self.canonical_count,\n                "observation_ids": self.observation_ids,\n                "source_market_ids": self.source_market_ids,\n                "content_hashes": self.content_hashes,\n                "replay_hashes": self.replay_hashes,\n                "read_only": self.read_only,\n                "execution_allowed": self.execution_allowed,\n                "execution_adapter_resolved": (\n                    self.execution_adapter_resolved\n                ),\n                "execution_adapter_invoked": (\n                    self.execution_adapter_invoked\n                ),\n                "trade_authorization_allowed": (\n                    self.trade_authorization_allowed\n                ),\n                "order_placement_allowed": (\n                    self.order_placement_allowed\n                ),\n                "funds_moved": self.funds_moved,\n                "portfolio_mutated": self.portfolio_mutated,\n                "capture_hash": self.capture_hash,\n            }\n        )\n\n\nclass OracleCanonicalPersistedCohortCapturePort:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(self) -> None:\n        self._lock = RLock()\n        self._pending: dict[\n            str,\n            CanonicalPersistedCohortCapture,\n        ] = {}\n        self._consumed_batch_ids: set[str] = set()\n\n    def capture(\n        self,\n        *,\n        canonical_observations: Sequence[CanonicalObservation],\n    ) -> CanonicalPersistedCohortCapture:\n        capture = CanonicalPersistedCohortCapture.create(\n            canonical_observations=canonical_observations,\n        )\n\n        batch_id = capture.acquisition_batch_id\n\n        with self._lock:\n            if batch_id in self._pending:\n                raise CanonicalPersistedCohortCaptureContractError(\n                    "acquisition batch already captured"\n                )\n\n            if batch_id in self._consumed_batch_ids:\n                raise CanonicalPersistedCohortCaptureContractError(\n                    "consumed acquisition batch cannot be recaptured"\n                )\n\n            self._pending[batch_id] = capture\n\n        return capture\n\n    def consume(\n        self,\n        *,\n        acquisition_batch_id: str,\n    ) -> CanonicalPersistedCohortCapture:\n        batch_id = _require_non_empty_string(\n            acquisition_batch_id,\n            "acquisition_batch_id",\n        )\n\n        with self._lock:\n            if batch_id in self._consumed_batch_ids:\n                raise CanonicalPersistedCohortCaptureContractError(\n                    "acquisition batch already consumed"\n                )\n\n            capture = self._pending.pop(\n                batch_id,\n                None,\n            )\n\n            if capture is None:\n                raise CanonicalPersistedCohortCaptureContractError(\n                    "no pending canonical cohort capture for batch"\n                )\n\n            capture.assert_invariants()\n            self._consumed_batch_ids.add(batch_id)\n\n        return capture\n\n    def peek_metadata(\n        self,\n        *,\n        acquisition_batch_id: str,\n    ) -> Mapping[str, Any] | None:\n        batch_id = _require_non_empty_string(\n            acquisition_batch_id,\n            "acquisition_batch_id",\n        )\n\n        with self._lock:\n            capture = self._pending.get(batch_id)\n\n            if capture is None:\n                return None\n\n            return capture.to_canonical_metadata()\n\n    @property\n    def pending_count(self) -> int:\n        with self._lock:\n            return len(self._pending)\n\n    @property\n    def consumed_count(self) -> int:\n        with self._lock:\n            return len(self._consumed_batch_ids)\n\n\n_GLOBAL_CAPTURE_PORT = OracleCanonicalPersistedCohortCapturePort()\n\n\ndef canonical_persisted_cohort_capture_port(\n) -> OracleCanonicalPersistedCohortCapturePort:\n    return _GLOBAL_CAPTURE_PORT\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_canonical_persisted_cohort_capture_port import (\n    CanonicalPersistedCohortCaptureContractError,\n    OracleCanonicalPersistedCohortCapturePort,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(2026, 7, 14, 13, 0, 0, tzinfo=timezone.utc)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    batch_id="batch.ola.040.1",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": "0.6140",\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi." + market_id + "." + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id=batch_id,\n    )\n\n\ndef build_cohort(\n    *,\n    batch_id="batch.ola.040.1",\n):\n    return tuple(\n        build_observation(\n            market_id=f"KXTEST-CAPTURE-{index}",\n            frame_id=str(index),\n            batch_id=batch_id,\n        )\n        for index in range(1, 6)\n    )\n\n\ndef run_capture_test():\n    port = OracleCanonicalPersistedCohortCapturePort()\n    cohort = build_cohort()\n\n    capture = port.capture(\n        canonical_observations=cohort\n    )\n\n    assert capture.schema_version == "OLA-040"\n    assert capture.engine_id == "OLA-040"\n    assert capture.acquisition_batch_id == "batch.ola.040.1"\n    assert capture.canonical_count == 5\n    assert capture.canonical_observations == cohort\n    assert all(\n        captured is original\n        for captured, original in zip(\n            capture.canonical_observations,\n            cohort,\n        )\n    )\n    assert capture.observation_ids == tuple(\n        observation.observation_id\n        for observation in cohort\n    )\n    assert capture.content_hashes == tuple(\n        observation.content_hash\n        for observation in cohort\n    )\n    assert capture.replay_hashes == tuple(\n        observation.replay_hash\n        for observation in cohort\n    )\n    assert port.pending_count == 1\n    assert port.consumed_count == 0\n\n    return port, capture, cohort\n\n\ndef run_consume_test():\n    port, capture, cohort = run_capture_test()\n\n    consumed = port.consume(\n        acquisition_batch_id=capture.acquisition_batch_id\n    )\n\n    assert consumed == capture\n    assert all(\n        captured is original\n        for captured, original in zip(\n            consumed.canonical_observations,\n            cohort,\n        )\n    )\n    assert port.pending_count == 0\n    assert port.consumed_count == 1\n\n    return port, consumed\n\n\ndef run_duplicate_capture_fail_closed_test():\n    port = OracleCanonicalPersistedCohortCapturePort()\n    cohort = build_cohort()\n\n    port.capture(canonical_observations=cohort)\n\n    try:\n        port.capture(canonical_observations=cohort)\n        raise AssertionError(\n            "duplicate batch capture must fail closed"\n        )\n    except CanonicalPersistedCohortCaptureContractError:\n        pass\n\n    assert port.pending_count == 1\n    assert port.consumed_count == 0\n\n\ndef run_duplicate_consume_fail_closed_test():\n    port, capture = run_consume_test()\n\n    try:\n        port.consume(\n            acquisition_batch_id=capture.acquisition_batch_id\n        )\n        raise AssertionError(\n            "duplicate batch consume must fail closed"\n        )\n    except CanonicalPersistedCohortCaptureContractError:\n        pass\n\n    assert port.pending_count == 0\n    assert port.consumed_count == 1\n\n\ndef run_recapture_consumed_batch_fail_closed_test():\n    port = OracleCanonicalPersistedCohortCapturePort()\n    cohort = build_cohort()\n\n    capture = port.capture(\n        canonical_observations=cohort\n    )\n    port.consume(\n        acquisition_batch_id=capture.acquisition_batch_id\n    )\n\n    try:\n        port.capture(canonical_observations=cohort)\n        raise AssertionError(\n            "consumed batch recapture must fail closed"\n        )\n    except CanonicalPersistedCohortCaptureContractError:\n        pass\n\n    assert port.pending_count == 0\n    assert port.consumed_count == 1\n\n\ndef run_mixed_batch_fail_closed_test():\n    port = OracleCanonicalPersistedCohortCapturePort()\n    cohort = list(build_cohort())\n\n    cohort[-1] = build_observation(\n        market_id="KXTEST-CAPTURE-5",\n        frame_id="mixed",\n        batch_id="batch.ola.040.other",\n    )\n\n    try:\n        port.capture(canonical_observations=cohort)\n        raise AssertionError(\n            "mixed acquisition batch identity must fail closed"\n        )\n    except CanonicalPersistedCohortCaptureContractError:\n        pass\n\n    assert port.pending_count == 0\n\n\ndef run_duplicate_market_fail_closed_test():\n    port = OracleCanonicalPersistedCohortCapturePort()\n    cohort = list(build_cohort())\n\n    cohort[-1] = build_observation(\n        market_id="KXTEST-CAPTURE-4",\n        frame_id="duplicate-market",\n    )\n\n    try:\n        port.capture(canonical_observations=cohort)\n        raise AssertionError(\n            "duplicate market identity must fail closed"\n        )\n    except CanonicalPersistedCohortCaptureContractError:\n        pass\n\n    assert port.pending_count == 0\n\n\ndef run_peek_metadata_test():\n    port, capture, _ = run_capture_test()\n\n    metadata = port.peek_metadata(\n        acquisition_batch_id=capture.acquisition_batch_id\n    )\n\n    assert metadata is not None\n    assert metadata["schema_version"] == "OLA-040"\n    assert metadata["canonical_count"] == 5\n    assert "canonical_observations" not in metadata\n\n    try:\n        metadata["canonical_count"] = 99\n        raise AssertionError(\n            "peek metadata must be immutable"\n        )\n    except TypeError:\n        pass\n\n    assert port.pending_count == 1\n\n\ndef run_deterministic_capture_hash_test():\n    first = OracleCanonicalPersistedCohortCapturePort()\n    second = OracleCanonicalPersistedCohortCapturePort()\n\n    first_capture = first.capture(\n        canonical_observations=build_cohort()\n    )\n    second_capture = second.capture(\n        canonical_observations=build_cohort()\n    )\n\n    assert first_capture == second_capture\n    assert first_capture.capture_hash == second_capture.capture_hash\n\n    return first_capture\n\n\ndef main():\n    _, capture, _ = run_capture_test()\n    _, consumed = run_consume_test()\n\n    run_duplicate_capture_fail_closed_test()\n    run_duplicate_consume_fail_closed_test()\n    run_recapture_consumed_batch_fail_closed_test()\n    run_mixed_batch_fail_closed_test()\n    run_duplicate_market_fail_closed_test()\n    run_peek_metadata_test()\n\n    deterministic = run_deterministic_capture_hash_test()\n\n    result = {\n        "schema_version": capture.schema_version,\n        "engine_id": capture.engine_id,\n        "status": "passed",\n        "exact_canonical_observation_objects_preserved": True,\n        "exact_observation_order_preserved": True,\n        "single_acquisition_batch_identity_enforced": True,\n        "unique_observation_identity_enforced": True,\n        "unique_market_identity_enforced": True,\n        "content_hash_binding_preserved": True,\n        "replay_hash_binding_preserved": True,\n        "write_once_per_batch": True,\n        "consume_once_per_batch": True,\n        "consumed_batch_recapture_fails_closed": True,\n        "mixed_batch_identity_fails_closed": True,\n        "duplicate_market_identity_fails_closed": True,\n        "immutable_metadata_projection": True,\n        "canonical_observation_objects_excluded_from_metadata": True,\n        "scheduler_kwargs_unchanged": True,\n        "scheduler_results_unchanged": True,\n        "deterministic_capture_hash_valid": (\n            deterministic.capture_hash == capture.capture_hash\n        ),\n        "capture_consumed_successfully": (\n            consumed.acquisition_batch_id\n            == capture.acquisition_batch_id\n        ),\n        "no_persistence_owned": True,\n        "no_lineage_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": capture.read_only,\n        "execution_allowed": capture.execution_allowed,\n        "execution_adapter_resolved": (\n            capture.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            capture.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            capture.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            capture.order_placement_allowed\n        ),\n        "funds_moved": capture.funds_moved,\n        "portfolio_mutated": capture.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-040 Oracle Canonical Persisted "\n        "Cohort Capture Port"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source, encoding="utf-8", newline="\n")
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-040 INSTALLER")
    print(" CANONICAL PERSISTED COHORT CAPTURE PORT")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-040 Oracle Canonical Persisted "
        "Cohort Capture Port installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_040_oracle_canonical_"
        "persisted_cohort_capture_port.py"
    )


if __name__ == "__main__":
    main()
